import itertools

def solve_2d(N, s):
    # This is too large for brute force.
    # Let's try all subsets of tiles for very small N, s.
    possible_tiles = []
    for x in range(1, N - s + 2):
        for y in range(1, N - s + 2):
            possible_tiles.append((x, y))

    max_k = 0
    # Sample subsets of tiles
    import random
    for _ in range(1000):
        T = random.sample(possible_tiles, random.randint(0, len(possible_tiles)))
        c = [[0]*N for _ in range(N)]
        for (tx, ty) in T:
            for i in range(tx-1, tx-1+s):
                for j in range(ty-1, ty-1+s):
                    c[i][j] += 1

        counts = {}
        for i in range(N):
            for j in range(N):
                v = c[i][j]
                if v > 0:
                    counts[v] = counts.get(v, 0) + 1
        if counts:
            max_k = max(max_k, max(counts.values()))
    return max_k

