    for x in range(1, N - s + 2):
        for y in range(1, N - s + 2):
            possible_tiles.append((x, y))

    # We can't brute force all subsets.
    # Let's try a more systematic search.
    max_k = 0
    for T_size in range(1, len(possible_tiles) + 1):
        # Randomly sample a few subsets of this size.
        import random
        for _ in range(100):
            T = random.sample(possible_tiles, T_size)
            c = [[0]*N for _ in range(N)]
            for (tx, ty) in T:
